// app/contact/Contact.tsx  <-- WRONG filename for a route
// Next.js only treats page.tsx as the route file; Contact.tsx is
// just a colocated component and is ignored by the router.
function App() {
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Contact</h2>
      <p>This file is named Contact.tsx, not page.tsx, so /contact is 404.</p>
    </div>
  );
}

solution.code:
// app/contact/page.tsx  <-- correct: page.tsx makes /contact routable
function App() {
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Contact</h2>
      <p>Renamed to page.tsx, so /contact now resolves.</p>
    </div>
  );
}

// app/blog/layout.tsx — shared shell for all blog routes
export default function BlogLayout({ children }: { children: React.ReactNode }) {
  return <section className="blog"><h1>Blog</h1>{children}</section>;
}

// app/blog/loading.tsx — shown while a blog route loads
export default function Loading() {
  return <p>Loading posts…</p>;
}

// app/blog/page.tsx — the list at /blog
export default async function BlogList() {
  const posts = await fetch('https://api/posts').then(r => r.json());
  return <ul>{posts.map((p: any) => <li key={p.slug}>{p.title}</li>)}</ul>;
}

// app/blog/[slug]/page.tsx — an individual post at /blog/:slug
export default async function Post({ params }: { params: { slug: string } }) {
  const post = await fetch(`https://api/posts/${params.slug}`).then(r => r.json());
  return <article><h2>{post.title}</h2><p>{post.body}</p></article>;
}

